"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9728],{24e3:e=>{e.exports=JSON.parse('{"functions":[{"name":"_move","desc":"Rotates the door by `amount` degrees over `duration`, optionally starting\\nfrom an existing angle.\\n\\nGuarded by the `moving` flag so a second call while a swing is in flight is\\nignored rather than fighting it. **Yields** until the swing completes, so\\n[Door:open] and [Door:close] return with the door already at rest.","params":[{"name":"amount","desc":"degrees to rotate, negative to swing back","lua_type":"number"},{"name":"fromAngle","desc":"current angle to rotate from, defaults to closed","lua_type":"number?"}],"returns":[],"function_type":"method","private":true,"source":{"line":64,"path":"src/Server/Class/Door.luau"}},{"name":"open","desc":"Swings the door open to `angle` degrees, playing the `Open` sound if the\\npart has one. No-ops when already open. Yields until the swing finishes.\\n\\nThe angle is remembered as `lastAngle` so [Door:close] knows how far to\\nswing back \u2014 a door can therefore be opened to different angles at\\ndifferent times.","params":[{"name":"angle","desc":"degrees to open by; required","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":112,"path":"src/Server/Class/Door.luau"}},{"name":"close","desc":"Swings the door back to closed by rotating `-lastAngle` from its current\\nposition, then plays the `Close` sound. No-ops when already closed. Yields\\nuntil the swing finishes.","params":[],"returns":[],"function_type":"method","source":{"line":139,"path":"src/Server/Class/Door.luau"}},{"name":"new","desc":"Builds a door from a part carrying a `Hinge` attachment, asserting that the\\npart and hinge both exist.\\n\\nCaptures the hinge\'s world position and orientation as the pivot, and the\\ninverse of its local position as the panel offset. Both are snapshotted here,\\nso moving the hinge afterwards will not be picked up.","params":[{"name":"data","desc":"the door part and swing duration (default 0.6s)","lua_type":"{ duration: number?, obj: BasePart }"}],"returns":[{"desc":"","lua_type":"Door"}],"function_type":"static","source":{"line":170,"path":"src/Server/Class/Door.luau"}}],"properties":[],"types":[],"name":"Door","desc":"A swinging door driven by CFrame rotation about a hinge attachment.\\n\\nThe door part must contain an Attachment named `Hinge`. Two CFrames are\\nderived from it at construction and never recomputed: `hingeOrigin`, the\\nhinge\'s world pivot, and `doorLength`, the inverse of the hinge\'s local\\noffset. Every frame the door is positioned as\\n`hingeOrigin * rotation * doorLength`, which swings the panel around the\\nhinge rather than its own centre.\\n\\nRotation is animated on `RunService.Stepped` over `duration` seconds, and\\nsnapped to the exact target angle on the final frame so accumulated\\nfloating-point drift cannot leave the door slightly ajar.\\n\\nOptional `Open` and `Close` Sound children are played when present.\\n\\n```lua\\nlocal door = Door.new({ obj = workspace.Door, duration = 0.6 })\\ndoor:open(90)\\ndoor:close()\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":29,"path":"src/Server/Class/Door.luau"}}')}}]);